```python
# AWS IAM Privilege Escalation Path Finder
import boto3
import json
from collections import defaultdict

class IAMEscalationFinder:
    # Known escalation vectors and required permissions
    ESCALATION_VECTORS = {
        'PassRole+EC2': ['iam:PassRole', 'ec2:RunInstances'],
        'PassRole+Lambda': ['iam:PassRole', 'lambda:CreateFunction'],
        'CreateAccessKey': ['iam:CreateAccessKey'],
        'CreateLoginProfile': ['iam:CreateLoginProfile'],
        'UpdateLoginProfile': ['iam:UpdateLoginProfile'],
        'AttachUserPolicy': ['iam:AttachUserPolicy'],
        'AttachRolePolicy': ['iam:AttachRolePolicy'],
        'PutRolePolicy': ['iam:PutRolePolicy'],
        'CreatePolicyVersion': ['iam:CreatePolicyVersion'],
        'SetDefaultPolicyVersion': ['iam:SetDefaultPolicyVersion'],
        'AssumeRole': ['sts:AssumeRole'],
        'UpdateFunctionCode': ['lambda:UpdateFunctionCode'],
    }

    def __init__(self):
        self.iam = boto3.client('iam')
        self.findings = []

    def get_user_permissions(self, user_name):
        """Get all permissions for a user (direct + group policies)"""
        permissions = set()

        # Get user attached policies
        user_policies = self.iam.list_attached_user_policies(
            UserName=user_name
        )
        for policy in user_policies['AttachedPolicies']:
            permissions.update(self._get_policy_permissions(policy['Arn']))

        # Get user group policies
        groups = self.iam.list_groups_for_user(UserName=user_name)
        for group in groups['Groups']:
            group_policies = self.iam.list_attached_group_policies(
                GroupName=group['GroupName']
            )
            for policy in group_policies['AttachedPolicies']:
                permissions.update(self._get_policy_permissions(policy['Arn']))

        # Get inline policies
        inline = self.iam.list_user_policies(UserName=user_name)
        for policy_name in inline['PolicyNames']:
            doc = self.iam.get_user_policy(
                UserName=user_name, PolicyName=policy_name
            )
            permissions.update(self._extract_actions(doc['PolicyDocument']))

        return permissions

    def _get_policy_permissions(self, policy_arn):
        """Extract allowed actions from a policy"""
        permissions = set()
        version = self.iam.get_policy(PolicyArn=policy_arn)
        doc = self.iam.get_policy_version(
            PolicyArn=policy_arn,
            VersionId=version['Policy']['DefaultVersionId']
        )
        return self._extract_actions(doc['PolicyVersion']['Document'])

    def _extract_actions(self, policy_doc):
        """Extract actions from a policy document"""
        actions = set()
        statements = policy_doc.get('Statement', [])
        if isinstance(statements, dict):
            statements = [statements]
        for stmt in statements:
            if stmt.get('Effect') == 'Allow':
                stmt_actions = stmt.get('Action', [])
                if isinstance(stmt_actions, str):
                    stmt_actions = [stmt_actions]
                for action in stmt_actions:
                    actions.add(action.lower())
        return actions

    def find_escalation_paths(self, user_name):
        """Find all privilege escalation paths for a user"""
        permissions = self.get_user_permissions(user_name)
        paths = []

        for vector_name, required in self.ESCALATION_VECTORS.items():
            if all(self._permission_grants(perm, permissions) for perm in required):
                paths.append({
                    'vector': vector_name,
                    'required': required,
                    'severity': 'CRITICAL' if 'Admin' in vector_name or 'Policy' in vector_name else 'HIGH'
                })

        # Check for wildcard permissions (effectively admin)
        if '*' in permissions or 'iam:*' in permissions:
            paths.append({
                'vector': 'Wildcard/Admin',
                'required': ['*'],
                'severity': 'CRITICAL'
            })

        return paths

    def _permission_grants(self, required, permissions):
        """Check if permissions grant the required action"""
        required_service = required.split(':')[0]
        required_action = required.split(':')[1]

        for perm in permissions:
            if perm == '*':
                return True
            if perm == f'{required_service}:*':
                return True
            if perm == required.lower():
                return True
        return False

# Usage
finder = IAMEscalationFinder()
for user in ['dev-user', 'intern-user', 'contractor-user']:
    paths = finder.find_escalation_paths(user)
    if paths:
        print(f"\n⚠️  {user}: {len(paths)} escalation paths found")
        for path in paths:
            print(f"  [{path['severity']}] {path['vector']}: {path['required']}")
    else:
        print(f"\n✅ {user}: No direct escalation paths")
